// Validate and extract input parameters
const body = $input.first().json.body;

const origin = body.origin;
const destination = body.destination;
const departureDate = body.departure_date;
const returnDate = body.return_date || null;

// Validate required fields
if (!origin || !destination || !departureDate) {
  throw new Error('Missing required fields: origin, destination, and departure_date are required');
}

// Validate date format (YYYY-MM-DD)
const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
if (!dateRegex.test(departureDate)) {
  throw new Error('Invalid departure_date format. Use YYYY-MM-DD');
}

if (returnDate && !dateRegex.test(returnDate)) {
  throw new Error('Invalid return_date format. Use YYYY-MM-DD');
}

return {
  origin: origin,
  destination: destination,
  departure_date: departureDate,
  return_date: returnDate,
  is_round_trip: returnDate !== null
};

// Aggregate results from all SerpAPI calls
const items = $input.all();

let flightsData = {};
let hotelsData = {};
let activitiesData = {};

// Process each item based on its source
for (const item of items) {
  const json = item.json;

  if (json.best_flights || json.other_flights) {
    flightsData = json;
  } else if (json.properties) {
    hotelsData = json;
  } else if (json.organic_results || json.ai_overview) {
    activitiesData = json;
  }
}

// Get the original search parameters from the first item's context
const searchParams = {
  origin: items[0]?.json?.search_parameters?.departure_id || 'Unknown',
  destination: items[0]?.json?.search_parameters?.arrival_id || 'Unknown',
  departure_date: items[0]?.json?.search_parameters?.outbound_date || 'Unknown',
  return_date: items[0]?.json?.search_parameters?.return_date || null
};

return {
  search_params: searchParams,
  flights: flightsData,
  hotels: hotelsData,
  activities: activitiesData
};

values.content:
You are a professional travel assistant helping users plan their trips. Based on the following travel data, create a comprehensive, well-formatted Markdown summary.

## Search Parameters:
- Origin: {{ $json.search_params.origin }}
- Destination: {{ $json.search_params.destination }}
- Departure Date: {{ $json.search_params.departure_date }}
{{ $json.search_params.return_date ? '- Return Date: ' + $json.search_params.return_date : '- Trip Type: One-way' }}

## Flight Data:
{{ JSON.stringify($json.flights, null, 2) }}

## Hotel Data:
{{ JSON.stringify($json.hotels, null, 2) }}

## Activities & Attractions:
{{ JSON.stringify($json.activities, null, 2) }}

---

Please create a comprehensive travel summary in Markdown format including:

1. **✈️ Flight Options** - Top 3-5 recommended flights with prices, airlines, duration, and stops. Include both best value and fastest options if available.

2. **🏨 Accommodation Recommendations** - Top 3-5 hotels with ratings, prices per night, and key amenities. Categorize by budget, mid-range, and luxury if possible.

3. **🎯 Things to Do** - Top 5-10 recommended activities and attractions at the destination. Include a mix of cultural sites, outdoor activities, dining, and entertainment.

4. **💰 Estimated Budget Summary** - A rough estimate of total trip costs including flights, accommodation (per night), and activities.

5. **📝 Travel Tips** - Any relevant tips for the destination based on the travel dates.

Make the response engaging, informative, and easy to read. Use emojis appropriately to make it visually appealing. If any data is unavailable, mention that the information could not be retrieved and suggest alternatives.

