// Format the final response
const geminiResponse = $input.first().json;

// Extract the markdown content from Gemini's response
let markdownContent = '';

if (geminiResponse.text) {
  markdownContent = geminiResponse.text;
} else if (geminiResponse.message?.content) {
  markdownContent = geminiResponse.message.content;
} else if (typeof geminiResponse === 'string') {
  markdownContent = geminiResponse;
} else {
  markdownContent = '# Travel Search Results\n\nUnable to generate summary. Please try again later.';
}

return {
  success: true,
  markdown: markdownContent,
  generated_at: new Date().toISOString()
};
